package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalGroupedRounds.*;
import org.kanger.ContextUniversalGroupedRounds.Result;
import org.kanger.ContextWitnessResultTransport.*;
import static org.kanger.ContextUniversalContinuationMatrix.*;

/** QA only: exact physical rule/donor alternatives and genuine grade-only improvement. */
final class ContextUniversalSourceAlternativesMatrix {
    static Set<Source> sources(Source... values){return new HashSet<>(Arrays.asList(values));}
    static Map<Set<Source>,Integer> supports(List<Support> values){Map<Set<Source>,Integer> result=new HashMap<>();for(Support s:values)require(result.put(new HashSet<>(s.sources),s.depth)==null,"one selected minimum per EXACT physical Source set");return result;}
    static final class Fixture {
        final Snapshot x,a,c,b,d;final Packet common;final Map<Cut,PrivatePool> pools=new LinkedHashMap<>();final Set<Source> seeds=new HashSet<>();
        Fixture()throws Exception {
            x=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);");a=bind(false,"!$u a(u,1);");c=bind(false,"!$u a(u,1);");
            b=bind(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2); !@u @v r(u,v)->r(u,v);");
            d=bind(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2);");common=ContextPrivateWitnessPoolRunner.common(x);
            for(Snapshot cut:Arrays.asList(a,c)){PrivatePool pool=ContextWitnessResultTransport.privatePool(common,x,cut,WORK);pools.put(pool.cut,pool);seeds.addAll(pool.sources);}require(pools.size()==2&&seeds.size()==2,"two distinct original private Contexts/seed Sources");
        }
        Map<Set<Source>,Integer> expected(Source seed,boolean fixed){Map<Set<Source>,Integer> expected=new HashMap<>();for(Snapshot donor:Arrays.asList(b,d))for(boolean loop:new boolean[]{false,true}){Set<Source> base=sources(x.primary.get(1).source,seed,donor.primary.get(0).source);if(loop)base.add(b.primary.get(3).source);if(fixed){for(Snapshot rule:Arrays.asList(b,d))for(Snapshot need:Arrays.asList(b,d)){Set<Source> full=new HashSet<>(base);full.add(rule.primary.get(1).source);full.add(need.primary.get(2).source);require(expected.put(full,loop?4:3)==null,"distinct whole rule/donor/loop Source combinations");}}else require(expected.put(base,loop?3:2)==null,"distinct symbolic donor/loop Source combinations");}return expected;}
        void products(Result r){
            Set<Origin> origins=ContextUniversalPrivateSymbolicMatrix.origins(r.output.packet,"s");require(origins.size()==2&&origins.stream().allMatch(o->o.binder==0&&seeds.contains(o.source)),"two original rigid Context Origins survive equivalent derivations");
            for(Item i:r.output.packet.items)if(i.atom.predicate.equals("s")){Origin o=i.atom.arguments.get(0).origin;Map<Set<Source>,Integer> actual=supports(i.proofs),expected=expected(o.source,true);require(i.atom.positive&&i.proofs.size()==16&&actual.equals(expected),"ALL sixteen exact fixed Source-grade alternatives, not subset pruning");for(Set<Source> set:actual.keySet())if(!set.contains(b.primary.get(3).source)){Set<Source> superset=new HashSet<>(set);superset.add(b.primary.get(3).source);require(actual.get(set)==3&&actual.get(superset)==4&&superset.containsAll(set)&&superset.size()==set.size()+1,"shorter subset NEVER deletes deeper genuine loop Source superset");}}
            Map<Origin,List<Support>> symbolic=new HashMap<>();for(ContextUniversalSignedUnitExchange.Unit u:r.symbolicOutput.units){require(ContextUniversalPrivateSymbolicMatrix.literal(u.clause,"r",true)&&u.clause.literals.size()==1&&u.clause.variables.size()==1&&u.clause.origins.size()==1,"symbolic r keeps free variable separate from rigid Origin");symbolic.computeIfAbsent(u.clause.origins.iterator().next(),key->new ArrayList<>()).add(u.support);}
            require(symbolic.keySet().equals(origins)&&r.symbolicOutput.units.size()==8&&r.compoundOutput.clauses.size()==21,"whole eight-unit/twenty-one-compound actual carrier inventory retained");for(Origin o:origins)require(supports(symbolic.get(o)).equals(expected(o.source,false)),"ALL four exact symbolic Source-grade alternatives per Origin");
            Set<Origin> routes=new HashSet<>();for(Round row:r.history)for(ConstraintTransfer t:row.barrier.branches.values())for(ContextUniversalOriginBindings.Route route:t.bindings.routes)routes.add(route.origin);require(routes.containsAll(origins),"actual theorem-specific parameter routes cover both private Contexts");
            require(r.output.packet.items.size()==3&&r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("a")||i.atom.predicate.equals("b")||i.atom.predicate.equals("need")||i.atom.predicate.equals("r")),"anchor and two proved s only, no raw donor/private or fabricated fixed-r disclosure");
            require(r.output.privatePools.keySet().equals(pools.keySet()),"same complete original private cut inventory");for(Cut cut:pools.keySet()){PrivatePool before=pools.get(cut),after=r.output.privatePools.get(cut);require(after.snapshot==before.snapshot&&after.sources.equals(before.sources)&&after.declarations.size()==before.declarations.size()&&after.local.items.stream().filter(i->i.atom.predicate.equals("a")).count()==1&&ContextUniversalPrivateSymbolicMatrix.origins(after.local,"s").equals(origins),"own private manifest/raw seed and both proved common results preserved");require(before.common==common&&ContextUniversalPrivateSymbolicMatrix.origins(before.local,"s").isEmpty(),"original private pool immutable");}
            require(r.history.stream().anyMatch(row->row.commonChanged&&row.input.items.size()==row.barrier.packet.items.size()),"Source/grade progress at SAME fixed-fact count forces another full barrier");
        }
    }
    static void partition(int first)throws Exception {
        Fixture f=new Fixture();List<Snapshot> all=Arrays.asList(f.a,f.b,f.c,f.d);List<List<Snapshot>> permutations=ContextUniversalContinuationRefutationRunner.permutations(all);require(permutations.size()==24&&new HashSet<>(permutations).size()==24,"ALL twenty-four distinct four-cut permutations enumerated");Result previous=null;int count=0;
        for(List<Snapshot> order:permutations)if(order.get(0)==all.get(first)){Frame frame=new Frame(f.x,order,f.common,f.pools);Result r=ContextUniversalSeparatePrivateMatrix.continued(frame);f.products(r);if(previous!=null)same(previous,r);previous=r;++count;if(count==1){SessionRun shortRun=run(frame,1,WORK,4096);incomplete(shortRun,"one progressing round cannot claim saturation or publish a prefix");noStableAudit(frame,shortRun);SessionRun work=run(frame,8,1,4096);incomplete(work,"work refusal cannot discard Source alternatives and publish a partial result");noStableAudit(frame,work);}}
        require(count==6,"exact six permutations in this isolated first-cut partition");System.out.println("SOURCE_ALTERNATIVES first="+first+" orders="+count+" fixedAlternativesPerOrigin=16 symbolicAlternativesPerOrigin=4 properSupersetsPerOrigin=8");
    }
    static Frame ordinaryBarrier(Frame f){
        Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks=new LinkedHashMap<>();List<Snapshot> targets=new ArrayList<>();targets.add(null);targets.addAll(f.cuts);
        for(Snapshot target:targets){ContextUniversalFrozenConstraints.SessionClosure c=ContextUniversalFrozenConstraints.closeSignedCompoundsWithValidationReuse(ContextUniversalCompoundExchangeRunner.rows(f.x,target),f.input,null,f.units,f.compounds,16,16,512,256,WORK,4096);require(c.result.closed&&c.metrics.entries==0,c.result.reason);checks.put(target==null?Cut.of(f.x):Cut.of(target),c.result);}
        ConstraintBarrier barrier=ContextUniversalCompoundExchangeRunner.barrier(f.input,checks);ContextUniversalSignedUnitExchange.SessionCollection units=ContextUniversalSignedUnitExchange.collectWithValidationReuse(f.x,f.input,new ArrayList<>(checks.keySet()),checks,512,256,16,WORK,4096);ContextUniversalCompoundExchange.SessionCollection compounds=ContextUniversalCompoundExchange.collectWithValidationReuse(f.x,f.input,new ArrayList<>(checks.keySet()),checks,512,256,16,WORK,4096);require(units.collection.collected&&compounds.collection.collected&&units.metrics.entries==0&&compounds.metrics.entries==0,units.collection.reason+compounds.collection.reason);
        ContextUniversalSignedUnitExchange.SessionRebase u=ContextUniversalSignedUnitExchange.rebaseWithValidationReuse(units.collection.output,barrier,WORK,4096);ContextUniversalCompoundExchange.SessionRebase c=ContextUniversalCompoundExchange.rebaseWithValidationReuse(compounds.collection.output,barrier,WORK,4096);require(u.metrics.entries==0&&c.metrics.entries==0,"ordinary input assembly scopes close, no cross-pass cache");return new Frame(f.x,f.cuts,barrier.packet,barrier.privatePools,u.exchange,c.exchange);
    }
    static Map<Set<Source>,Integer> fixed(Packet p){return supports(p.items.stream().filter(i->i.atom.predicate.equals("r")).findFirst().get().proofs);}
    static Map<Set<Source>,Integer> gradeExpected(Snapshot x,Snapshot a,Snapshot b,boolean nativeGrades){Map<Set<Source>,Integer> result=new HashMap<>();for(Snapshot rule:Arrays.asList(a,b))for(Snapshot donor:Arrays.asList(a,b))for(boolean loop:new boolean[]{false,true}){Set<Source> set=sources(x.primary.get(1).source,rule.primary.get(0).source,donor.primary.get(1).source);if(loop)set.add(a.primary.get(2).source);int depth=(nativeGrades||rule==donor?1:2)+(loop?1:0);require(result.put(set,depth)==null,"eight distinct exact grade-only Source alternatives");}return result;}
    static void gradeOnly()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u);"),a=bind(false,"!@u p(u)&&b(u)->r(u); !b(1); !@u r(u)->r(u);"),b=bind(false,"!@u p(u)&&b(u)->r(u); !b(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Map<Set<Source>,Integer> oldExpected=gradeExpected(x,a,b,false),better=gradeExpected(x,a,b,true);
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Frame frame=new Frame(x,order,p,Collections.emptyMap()),previous=null;for(int i=0;i<3;++i){previous=frame;frame=ordinaryBarrier(frame);}require(ContextWitnessResultTransport.sameContents(previous.input,frame.input,WORK)&&ContextUniversalSignedUnitExchange.sameContents(previous.units,frame.units,WORK)&&ContextUniversalCompoundExchange.sameContents(previous.compounds,frame.compounds,WORK),"genuine ordinary sequential Source-grade pools unchanged at third pass");Map<Set<Source>,Integer> actualOld=fixed(frame.input);require(actualOld.equals(oldExpected)&&actualOld.size()==8,"actual old ordinary mixed minima1/2 plus loop2/3, no forged Support metadata");
            Result result=ContextUniversalSeparatePrivateMatrix.continued(frame);Map<Set<Source>,Integer> actualNew=fixed(result.output.packet);require(actualNew.equals(better)&&actualNew.keySet().equals(actualOld.keySet())&&result.output.packet.items.size()==frame.input.items.size(),"SAME facts and EXACT Source inventory, all native minima1 plus loop2");int improved=0;for(Set<Source> set:actualOld.keySet()){int delta=actualOld.get(set)-actualNew.get(set);require(delta==0||delta==1,"unchanged or exactly one-level shorter original Source proof");if(delta==1)++improved;}require(improved==4&&result.completedRounds>=2&&result.history.get(0).commonChanged&&result.history.get(0).input.items.size()==result.history.get(0).barrier.packet.items.size(),"FOUR grade-only improvements force another all-cut qualification at unchanged fact count");require(fixed(frame.input).equals(oldExpected),"original genuine old Source/grade frame immutable");}
        System.out.println("SOURCE_ALTERNATIVES_GRADE orders=2 exactSourceAlternatives=8 improvedPerOrder=4 properSupersets=4 oldAssemblyPasses=3 continuations=2");
    }
}
